// Asked for by a person, so every active source is checked now, due or not.
// chat_id is there when the ask came from Telegram, so the answer can go back.
return [{ json: { force: true, chat_id: $input.first().json.chat_id ?? null } }];

// When /check started this run, tell the editor what it found. A scheduled
// run has no chat to answer and stops here.
let chatId = null;
try { chatId = $('Check everything').first().json.chat_id; } catch (e) { chatId = null; }
if (!chatId) return [];

const r = $json;
let text;
if (!r.sources) {
  text = 'There are no sources to check. Tell Vinh.';
} else {
  const titles = r.new_titles || [];
  const lines = [`Checked ${r.sources} source${r.sources === 1 ? '' : 's'}.`];
  if (titles.length) {
    lines.push(`${titles.length} new article${titles.length === 1 ? '' : 's'}:`);
    for (const t of titles.slice(0, 10)) lines.push(`• ${t}`);
    if (titles.length > 10) lines.push(`and ${titles.length - 10} more`);
    lines.push('', 'Summaries will be ready within 15 minutes.');
  } else {
    lines.push('Nothing new since the last check.');
  }
  const problems = r.problems || [];
  if (problems.length) lines.push('', `${problems.length} source${problems.length === 1 ? '' : 's'} had a problem:`, ...problems.slice(0, 5).map(p => `• ${p}`));
  text = lines.join('\n');
}
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
  body: { chat_id: chatId, text, disable_web_page_preview: true },
  json: true,
});
return [{ json: { told: chatId } }];
